import { isApiReachable } from '../../db/api-reachability.js';
import { createComponentLogger } from '../../utils/component-logger.js';
import { SyncService, type SyncResult } from './sync.service.js';

/**
 * Story 359 — queued changes push on their own. Only the /status and /debug buttons ever called
 * `syncPendingChanges`, so an offline edit sat in the queue until someone tapped Sync, settings
 * written to the replica never reached the server's reminder tasks, and the replica stopped
 * refreshing for good (every cold boot queues `app.timezone`, and `refreshIfStale` waits while
 * anything is pending).
 *
 * Triggers: the `online` event, the page becoming visible, startup, and a synced-settings write.
 * Each pushes only when the API answers (`isApiReachable`, not `navigator.onLine` — DLR #229), and
 * overlapping triggers share one push. `syncPendingChanges` loops until the queue is empty and
 * ends with `refreshIfStale`, so a change queued mid-push still goes out in the same run.
 */
export type AutoSyncTrigger = 'online' | 'visible' | 'startup' | 'settings';

export interface AutoSyncDeps {
    isReachable: () => Promise<boolean>;
    sync: () => Promise<SyncResult>;
}

const log = createComponentLogger('auto-sync');

export function createAutoSync(deps: AutoSyncDeps): (trigger: AutoSyncTrigger) => Promise<SyncResult | null> {
    let inFlight: Promise<SyncResult | null> | null = null;

    const run = async (trigger: AutoSyncTrigger): Promise<SyncResult | null> => {
        if (!(await deps.isReachable())) {
            log.debug(`${trigger}: API unreachable — queued changes wait for the next trigger`);
            return null;
        }
        const result = await deps.sync();
        if (result.status === 'failed') {
            log.warn(`${trigger}: sync failed — the changes stay queued: ${result.error}`);
        } else if (result.applied > 0) {
            log.info(`${trigger}: pushed ${result.applied} queued change(s)`);
        }
        return result;
    };

    return (trigger) => {
        inFlight ??= run(trigger).finally(() => {
            inFlight = null;
        });
        return inFlight;
    };
}

export const syncQueuedChanges = createAutoSync({
    isReachable: () => isApiReachable(),
    sync: () => SyncService.syncPendingChanges(),
});

let armed = false;

/** app.ts arms the triggers after boot; until then (and in unit tests) requests are ignored. */
export function armAutoSync(): void {
    armed = true;
}

/**
 * Ask for a push from code that writes synced rows to the replica while online — the settings
 * services. Their rows reach the server only through the queue, so a toggled reminder category
 * would otherwise wait for the next online/visible/startup trigger.
 */
export function requestSync(trigger: AutoSyncTrigger): void {
    if (armed) void syncQueuedChanges(trigger);
}
